function getTargetBaseDir(t, cwd) {
  if (t === 'project') {
    return join(cwd, '.agents', 'skills')
  }

  const agent =
    getAgentByFlag(t) ||
    agents.find((candidate) => candidate.name === t)

  const baseDir = agent ? agent.getDir() : getAgentsDir()

  return rebaseToCwd(baseDir, cwd)
}
